    SELECT `sm`.`song_id` FROM `song_metadata` AS `sm`
    WHERE `sm`.`catalog_track_id` = '1c96c83ba513f44d'
       OR (`sm`.`catalog_track_id` IS NULL
           AND `sm`.`track_id` = '1c96c83ba513f44d'
           AND NOT EXISTS (
               SELECT 1 FROM `song_metadata` AS `preferred`
               WHERE `preferred`.`catalog_track_id` = '1c96c83ba513f44d'
           ))
    ORDER BY (`sm`.`catalog_track_id` = '1c96c83ba513f44d') DESC LIMIT 1
);
SET @song_id = COALESCE(@song_id, (
    SELECT `s`.`song_id` FROM `song` AS `s`
    WHERE `s`.`song_id` = '1c96c83ba513f44d' LIMIT 1
));
