SET @song_id = (
    SELECT `sm`.`song_id` FROM `song_metadata` AS `sm`
    WHERE `sm`.`catalog_track_id` = '2dd555e9046e4532'
       OR (`sm`.`catalog_track_id` IS NULL
           AND `sm`.`track_id` = '2dd555e9046e4532'
           AND NOT EXISTS (
               SELECT 1 FROM `song_metadata` AS `preferred`
               WHERE `preferred`.`catalog_track_id` = '2dd555e9046e4532'
           ))
    ORDER BY (`sm`.`catalog_track_id` = '2dd555e9046e4532') DESC LIMIT 1
);
