           AND `sm`.`track_id` = '9a72d935bbe8e15b'
           AND NOT EXISTS (
               SELECT 1 FROM `song_metadata` AS `preferred`
               WHERE `preferred`.`catalog_track_id` = '9a72d935bbe8e15b'
