-- catalog track: a6b795e492c3f8d0
SET @song_id = (
    SELECT `sm`.`song_id` FROM `song_metadata` AS `sm`
    WHERE `sm`.`catalog_track_id` = 'a6b795e492c3f8d0'
       OR (`sm`.`catalog_track_id` IS NULL
           AND `sm`.`track_id` = 'a6b795e492c3f8d0'
           AND NOT EXISTS (
               SELECT 1 FROM `song_metadata` AS `preferred`
               WHERE `preferred`.`catalog_track_id` = 'a6b795e492c3f8d0'
           ))
    ORDER BY (`sm`.`catalog_track_id` = 'a6b795e492c3f8d0') DESC LIMIT 1
);
SET @song_id = COALESCE(@song_id, (
    SELECT `s`.`song_id` FROM `song` AS `s`
    WHERE `s`.`song_id` = 'a6b795e492c3f8d0' LIMIT 1
));
