-- catalog track: cb239137f10233cb
SET @song_id = (
    SELECT `sm`.`song_id` FROM `song_metadata` AS `sm`
    WHERE `sm`.`catalog_track_id` = 'cb239137f10233cb'
       OR (`sm`.`catalog_track_id` IS NULL
           AND `sm`.`track_id` = 'cb239137f10233cb'
           AND NOT EXISTS (
               SELECT 1 FROM `song_metadata` AS `preferred`
               WHERE `preferred`.`catalog_track_id` = 'cb239137f10233cb'
           ))
    ORDER BY (`sm`.`catalog_track_id` = 'cb239137f10233cb') DESC LIMIT 1
);
SET @song_id = COALESCE(@song_id, (
    SELECT `s`.`song_id` FROM `song` AS `s`
    WHERE `s`.`song_id` = 'cb239137f10233cb' LIMIT 1
));
