    SELECT `sm`.`song_id` FROM `song_metadata` AS `sm`
    WHERE `sm`.`catalog_track_id` = 'cefc0cee6f26ed20'
       OR (`sm`.`catalog_track_id` IS NULL
           AND `sm`.`track_id` = 'cefc0cee6f26ed20'
           AND NOT EXISTS (
               SELECT 1 FROM `song_metadata` AS `preferred`
               WHERE `preferred`.`catalog_track_id` = 'cefc0cee6f26ed20'
           ))
    ORDER BY (`sm`.`catalog_track_id` = 'cefc0cee6f26ed20') DESC LIMIT 1
);
SET @song_id = COALESCE(@song_id, (
    SELECT `s`.`song_id` FROM `song` AS `s`
    WHERE `s`.`song_id` = 'cefc0cee6f26ed20' LIMIT 1
));
