       OR (`sm`.`catalog_track_id` IS NULL
           AND `sm`.`track_id` = '9810c515ee27adfc'
           AND NOT EXISTS (
               SELECT 1 FROM `song_metadata` AS `preferred`
               WHERE `preferred`.`catalog_track_id` = '9810c515ee27adfc'
