-- catalog track: 1e24b6960b949a7d
SET @song_id = (
    SELECT `sm`.`song_id` FROM `song_metadata` AS `sm`
    WHERE `sm`.`catalog_track_id` = '1e24b6960b949a7d'
       OR (`sm`.`catalog_track_id` IS NULL
           AND `sm`.`track_id` = '1e24b6960b949a7d'
           AND NOT EXISTS (
               SELECT 1 FROM `song_metadata` AS `preferred`
               WHERE `preferred`.`catalog_track_id` = '1e24b6960b949a7d'
           ))
    ORDER BY (`sm`.`catalog_track_id` = '1e24b6960b949a7d') DESC LIMIT 1
);
SET @song_id = COALESCE(@song_id, (
    SELECT `s`.`song_id` FROM `song` AS `s`
    WHERE `s`.`song_id` = '1e24b6960b949a7d' LIMIT 1
));
INSERT INTO `song` (`song_id`, `title`, `title_normalized`, `duration_ms`, `status`, `practice_ready`)
