WHERE @song_id IS NULL;
SET @song_id = COALESCE(@song_id, '1e24b6960b949a7d');
UPDATE `song`
SET `title` = 'Congratulations', `title_normalized` = 'congratulations',
    `duration_ms` = 229667, `status` = 'ACTIVE'
WHERE `song_id` = @song_id;

