       OR (`sm`.`catalog_track_id` IS NULL
           AND `sm`.`track_id` = 'a98507ad7e8ad829'
           AND NOT EXISTS (
               SELECT 1 FROM `song_metadata` AS `preferred`
               WHERE `preferred`.`catalog_track_id` = 'a98507ad7e8ad829'
