       OR (`sm`.`catalog_track_id` IS NULL
           AND `sm`.`track_id` = 'bba430f17c19add5'
           AND NOT EXISTS (
               SELECT 1 FROM `song_metadata` AS `preferred`
               WHERE `preferred`.`catalog_track_id` = 'bba430f17c19add5'
